"use strict";(self.webpackChunkstrapi_docs=self.webpackChunkstrapi_docs||[]).push([[88380],{64503:e=>{e.exports=JSON.parse('{"tag":{"label":"Document Service API","permalink":"/tags/document-service-api","allTagsPath":"/tags","count":17,"items":[{"id":"cms/backend-customization","title":"Back-end customization","description":"All elements of Strapi\'s back end, like routes, policies, middlewares, controllers, services, models, requests, responses, and webhooks, can be customized.","permalink":"/cms/backend-customization"},{"id":"cms/api/content-api","title":"Content API","description":"Learn more about Strapi 5\'s Content API","permalink":"/cms/api/content-api"},{"id":"cms/migration/v4-to-v5/breaking-changes/core-service-methods-use-document-service","title":"Core service methods use the Document Service API","description":"In Strapi 5, core service methods use the Document Service API instead of the Entity Service API.","permalink":"/cms/migration/v4-to-v5/breaking-changes/core-service-methods-use-document-service"},{"id":"cms/migration/v4-to-v5/breaking-changes/lifecycle-hooks-document-service","title":"Database lifecycle hooks are triggered differently with the Document Service API methods","description":"In Strapi 5, database lifecycle hooks are triggered differently with the various Document Service API methods.","permalink":"/cms/migration/v4-to-v5/breaking-changes/lifecycle-hooks-document-service"},{"id":"cms/api/document-service","title":"Document Service API","description":"The Document Service API is the recommended way to interact with your content from the back-end server or from plugins.","permalink":"/cms/api/document-service"},{"id":"cms/migration/v4-to-v5/breaking-changes/use-document-id","title":"documentId should be used instead of id in API calls","description":"Documents should be called by their documentId in Content API calls (REST API & GraphQL).","permalink":"/cms/migration/v4-to-v5/breaking-changes/use-document-id"},{"id":"cms/api/document","title":"Documents","description":"Learn what a Document is in Strapi v5","permalink":"/cms/api/document"},{"id":"cms/migration/v4-to-v5/breaking-changes/entity-service-deprecated","title":"Entity Service deprecated","description":"In Strapi 5, the Entity Service API is deprecated in favor of the new Document Service API.","permalink":"/cms/migration/v4-to-v5/breaking-changes/entity-service-deprecated"},{"id":"cms/migration/v4-to-v5/additional-resources/from-entity-service-to-document-service","title":"From Entity Service API to Document Service API","description":"Learn how to transition from the Entity Service API of Strapi v4 to the Document Service API in Strapi 5","permalink":"/cms/migration/v4-to-v5/additional-resources/from-entity-service-to-document-service"},{"id":"cms/migration/v4-to-v5/breaking-changes/no-find-page-in-document-service","title":"No findPage() in Document Service API","description":"In Strapi 5, the Entity Service API is deprecated, and for the findPage() method you should use the Document Service API\'s findMany() method instead.","permalink":"/cms/migration/v4-to-v5/breaking-changes/no-find-page-in-document-service"},{"id":"cms/migration/v4-to-v5/breaking-changes/publication-state-removed","title":"publicationState is removed and replaced by status","description":"In Strapi 5, \'publicationState\' can no longer be used in Content API calls. The new status parameter can be used and accepts 2 different values, draft and published.","permalink":"/cms/migration/v4-to-v5/breaking-changes/publication-state-removed"},{"id":"cms/api/document-service/status","title":"Using Draft & Publish with the Document Service API","description":"Use Strapi\'s Document Service API to return either the draft or the published version of a document","permalink":"/cms/api/document-service/status"},{"id":"cms/api/document-service/fields","title":"Using fields with the Document Service API","description":"Use Strapi\'s Document Service API to select the fields to return with your queries.","permalink":"/cms/api/document-service/fields"},{"id":"cms/api/document-service/filters","title":"Using filters with the Document Service API","description":"This document provides information about the filters available in the Document Service API.","permalink":"/cms/api/document-service/filters"},{"id":"cms/api/document-service/populate","title":"Using Populate with the Document Service API","description":"Use Strapi\'s Document Service API to populate or select some fields.","permalink":"/cms/api/document-service/populate"},{"id":"cms/api/document-service/sort-pagination","title":"Using Sort & Pagination with the Document Service API","description":"Use Strapi\'s Document Service API to sort and paginate query results","permalink":"/cms/api/document-service/sort-pagination"},{"id":"cms/api/document-service/locale","title":"Using the locale parameter with the Document Service API","description":"Use Strapi\'s Document Service API to work with locale versions with your queries.","permalink":"/cms/api/document-service/locale"}],"unlisted":false}}')}}]);